const cache = new Map();
export function uiClass(value = '') {
  if (!value) return '';
  if (cache.has(value)) return cache.get(value);
  const tokens = String(value).split(/\s+/).filter(Boolean);
  const result = new Set();
  for (const token of tokens) {
    if (!styles[token] || hooks.has(token)) result.add(token);
    if (styles[token]) for (const utility of styles[token].split(' ')) result.add(utility);
  }
  const classes = [...result].join(' ');
  if (cache.size > 2048) cache.clear();
  cache.set(value, classes);
  return classes;
}
